// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 depositAmount, uint256 useAttacker) public {
        depositAmount = bound(depositAmount, 1 wei, 5 ether);
        uint256 flag = useAttacker % 2;

        address caller;
        Attacker attacker;
        if (flag == 1) {
            attacker = new Attacker(address(c));
            caller = address(attacker);
        } else {
            caller = address(0xBEEF);
        }

        vm.deal(caller, depositAmount + 1 ether);

        vm.prank(caller);
        c.deposit{value: depositAmount}();

        uint256 before = address(c).balance;

        if (flag == 1) {
            attacker.setReenter(true);
        }

        vm.prank(caller);
        c.withdrawAll();

        if (flag == 1) {
            attacker.setReenter(false);
        }

        uint256 afterFirst = address(c).balance;

        vm.prank(caller);
        c.withdrawAll();

        uint256 afterSecond = address(c).balance;

        assertTrue(afterSecond == afterFirst);
    }
}

contract Attacker {
    address public target;
    bool public reenter;
    uint256 public called;

    constructor(address _target) {
        target = _target;
    }

    function setReenter(bool r) public {
        reenter = r;
    }

    receive() external payable {
        if (reenter && called == 0) {
            called += 1;
            ReentrancyDAO(target).withdrawAll();
        }
    }

    function depositToTarget() public payable {
        ReentrancyDAO(target).deposit{value: msg.value}();
    }
}
